### Iteration 2: Shared Memory Optimization
We'll use shared memory to load tiles of matrices A and B into fast on-chip memory, reducing global memory accesses.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define CUDA kernel source with shared memory optimization
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16

__global__ void matmul_kernel(const float* a, const float* b, float* out, int N) {
    // Shared memory for tiles of matrices A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Output row and column
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; t++) {
        // Load tile of A into shared memory
        int a_col = t * BLOCK_SIZE + tx;
        if (row < N && a_col < N) {
            As[ty][tx] = a[row * N + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = t * BLOCK_SIZE + ty;
        if (b_row < N && col < N) {
            Bs[ty][tx] = b[b_row * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();  // Wait for all threads to load tiles

        // Compute partial sum from tiles
