### Iteration 3: Register Blocking Optimization
We'll use register blocking to compute multiple elements per thread, reducing shared memory accesses and improving arithmetic intensity.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define CUDA kernel source with register blocking optimization
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define TILE_SIZE 2

__global__ void matmul_kernel(const float* a, const float* b, float* out, int N) {
    // Shared memory for tiles of matrices A and B
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Output row and column
    int row = by * BLOCK_SIZE + ty * TILE_SIZE;
    int col = bx * BLOCK_SIZE + tx * TILE_SIZE;

    // Register accumulators for each output element
    float sum[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; t++) {
        // Load tile of A into shared memory
        int a_col = t * BLOCK_SIZE + tx;
        if (row < N && a_col < N) {
            As[ty * TILE_SIZE][tx] = a[row * N + a_col];
        } else {
            As[ty * TILE_SIZE][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = t * BLOCK_SIZE + ty;
        if (b_row < N && col < N) {
            Bs[ty][tx * TILE_SIZE] = b[b_row * N + col];
        } else {
            Bs[ty][tx * TILE_SIZE] = 0.0f;
        }

        __syncthreads();  // Wait for all threads to load tiles

        // Compute partial sums using register blocking
        for (int k = 0; k < BLOCK_SIZE; k++) {
            float a_val = As[ty * TILE_SIZE][k];
            float b_val = Bs[k][tx * TILE_SIZE];

            sum[0][0] += a_val * b_val;
        }

        __syncthreads();  // Wait before loading next tiles
    }

    // Write results to output
    for (int i = 0; i < TILE_SIZE; i++) {
        for (int j = 0; j < TILE_SIZE; j++) {
            int out_row = row + i;
            int out_col = col + j;
            if (out_row < N && out_col < N) {
                out[out_row * N + out_col] = sum[i][j];
            }
        }
    }
}

torch::Tensor matmul_forward(torch::Tensor a, torch::Tensor b) {
    int N = a.size(0);
    auto out = torch::zeros_like(a);

    // Adjust block size for register blocking
    dim3 block(BLOCK_SIZE // TILE_SIZE, BLOCK_SIZE // TILE_SIZE);
    dim3 grid((N + block.x * TILE_SIZE - 1) / (block.x * TILE_SIZE), 
              (N + block.y * TILE_SIZE - 1) / (block.y * TILE_SIZE));

    matmul_kernel<<<grid, block>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), N);

    return out;
}
"""

